-- Aries RDS PostgreSQL Schema + Data
-- Compatible with AWS RDS PostgreSQL 14+

BEGIN;


CREATE TABLE IF NOT EXISTS domains (
    domain_id   SERIAL PRIMARY KEY,
    name        TEXT NOT NULL UNIQUE
);

CREATE TABLE IF NOT EXISTS departments (
    dept_id     SERIAL PRIMARY KEY,
    name        TEXT NOT NULL UNIQUE
);

CREATE TABLE IF NOT EXISTS clusters (
    cluster_id  INTEGER PRIMARY KEY,
    code        INTEGER NOT NULL,
    name        TEXT NOT NULL UNIQUE
);

CREATE TABLE IF NOT EXISTS categories (
    category_id  SERIAL PRIMARY KEY,
    slug         TEXT NOT NULL UNIQUE,
    question_count INTEGER DEFAULT 0
);

CREATE TABLE IF NOT EXISTS questions (
    question_id   SERIAL PRIMARY KEY,
    qid_code      TEXT NOT NULL UNIQUE,
    domain_id     INTEGER REFERENCES domains(domain_id),
    dept_id       INTEGER REFERENCES departments(dept_id),
    category_id   INTEGER REFERENCES categories(category_id),
    cluster_id    INTEGER REFERENCES clusters(cluster_id),
    question_text TEXT NOT NULL,
    response_type TEXT,
    trigger_points TEXT,
    is_universal  BOOLEAN DEFAULT FALSE
);

CREATE TABLE IF NOT EXISTS use_cases (
    use_case_id SERIAL PRIMARY KEY,
    name        TEXT NOT NULL UNIQUE
);

CREATE TABLE IF NOT EXISTS use_case_category_weights (
    weight_id    SERIAL PRIMARY KEY,
    use_case_id  INTEGER NOT NULL REFERENCES use_cases(use_case_id),
    category_id  INTEGER NOT NULL REFERENCES categories(category_id),
    weight       NUMERIC(6,2) NOT NULL,
    UNIQUE(use_case_id, category_id)
);

-- domains: 6 rows

-- departments: 10 rows

-- clusters: 7 rows

-- categories: 44 rows

-- questions: 559 rows

-- use_cases: 25 rows

-- use_case_category_weights: 193 rows

SELECT setval(pg_get_serial_sequence('domains', 'domain_id'), (SELECT MAX(domain_id) FROM domains));
SELECT setval(pg_get_serial_sequence('departments', 'dept_id'), (SELECT MAX(dept_id) FROM departments));
SELECT setval(pg_get_serial_sequence('categories', 'category_id'), (SELECT MAX(category_id) FROM categories));
SELECT setval(pg_get_serial_sequence('questions', 'question_id'), (SELECT MAX(question_id) FROM questions));
SELECT setval(pg_get_serial_sequence('use_cases', 'use_case_id'), (SELECT MAX(use_case_id) FROM use_cases));
SELECT setval(pg_get_serial_sequence('use_case_category_weights', 'weight_id'), (SELECT MAX(weight_id) FROM use_case_category_weights));

COMMIT;