INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (252, 'AR_252', 1, 2, 7, 2, 'Upon AI system retirement, are model artifacts securely archived or deleted in accordance with documented retention schedules, training and operational datasets disposed of in compliance with legal and cross-jurisdictional obligations, API endpoints and credentials formally revoked, and downstream system dependencies identified and assessed to prevent operational disruption?', 'Yes – All Retirement Controls Fully Applied & Documented | Partial – Some Controls Missing or Inconsistently Applied | No – Retirement Data Controls Not Defined', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (253, 'AR_253', 1, 6, 25, 3, 'Does the organization formally determine and document what AI system technical documentation must be prepared, maintained, and disclosed to defined categories of interested parties — including controlled disclosure procedures, format standards, version control requirements, and access authorization criteria?', 'Yes – Fully Defined, Documented & Governed | Partial – Partially Defined or Inconsistently Applied Across Systems | No – Not Formally Defined', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (254, 'AR_254', 1, 6, 18, 3, 'Are AI system event logging requirements formally defined across the lifecycle — covering log content scope, integrity protection mechanisms, retention duration, access controls, and log completeness — with periodic independent review to confirm logging remains accurate, complete, and tamper-evident?', 'Yes – Logging Requirements Fully Defined & Periodically Reviewed for Completeness | Partial – Requirements Defined but Review Gaps or Scope Deficiencies Exist | No – Not Formally Defined', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (255, 'AR_255', 1, 2, 7, 2, 'Has the organization formally defined and implemented an AI-specific data management process covering all lifecycle stages — with formally assigned data asset ownership (data stewards, model owners, control functions) and differentiated governance controls for training data, validation data, operational inference data, and repurposed operational data?', 'Yes – Process Established, Ownership Formally Assigned & Data Categories Differentiated | Partial – Process Exists but Ownership Assignments or Data Category Controls Inadequate | No – No Formal AI Data Management Process', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (256, 'AR_256', 1, 2, 7, 2, 'Has the organization defined formal criteria for AI data acquisition covering legal permissibility, licensing, privacy compliance, intellectual property rights, representativeness, and bias exposure — and for externally sourced or third-party data, does it document provenance, contractual restrictions, permitted uses, and risk assessments prior to integration into AI workflows?', 'Yes – Formal Criteria Defined & External Data Fully Assessed Before Integration | Partial – Criteria Exist but External Data Assessment Is Incomplete or Inconsistently Applied | No – No Formal Acquisition Criteria', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (257, 'AR_257', 1, 2, 7, 2, 'Has the organization defined measurable data quality requirements for AI systems — covering accuracy, completeness, representativeness, and bias thresholds — implemented validation mechanisms to verify that data meets these thresholds before use, and established a formal escalation process when data fails quality checks?', 'Yes – Requirements Defined, Validation Implemented & Escalation Process Formally Established | Partial – Requirements Defined but Validation Mechanisms or Escalation Process Incomplete | No – No Formal Data Quality Requirements', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (258, 'AR_258', 1, 2, 7, 2, 'Has the organization defined a lifecycle-based data provenance process — recording origin, transformations, labeling methods, preprocessing steps, version history, and usage across model iterations — and is this process technically enforced through system-level logging, metadata tagging, or data lineage tooling rather than relying on manual documentation alone?', 'Yes – Provenance Process Defined & Technically Enforced End-to-End | Partial – Process Defined but Relies Substantially on Manual Documentation | No – No Provenance Process', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (259, 'AR_259', 1, 2, 7, 2, 'Has the organization defined formal criteria for AI data preparation methods, evaluated preparation activities for unintended impacts — including bias amplification and privacy risk — and established documented reproducibility capability for the full data preparation pipeline, such that preparation steps can be reconstructed for audit or model retraining?', 'Yes – Criteria Defined, Impact Evaluation Conducted & Pipeline Fully Reproducible | Partial – Some Elements Missing or Inconsistently Applied | No – No Formal Data Preparation Governance', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (260, 'AR_260', 1, 2, 7, 2, 'Has the organization established a formal AI data classification framework that categorises datasets by sensitivity and risk criticality, with data handling controls — including access restriction, encryption, masking, and monitoring — applied proportionally to each classification level?', 'Yes – Framework in Place & Proportional Controls Consistently Applied | Partial – Framework Exists but Controls Not Fully Proportional or Consistently Enforced | No – No Data Classification Framework', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (261, 'AR_261', 1, 3, 3, 1, 'Does the organization evaluate and document risks of data poisoning, malicious injection, and adversarial manipulation in training datasets — and are technical and procedural controls implemented to detect and mitigate these threats, including integrity verification, anomaly detection, and dataset hashing?', 'Yes – Risks Formally Assessed & Comprehensive Technical and Procedural Controls Implemented | Partial – Risks Assessed but Controls Incomplete, Undocumented, or Reliant on Procedure Alone | No – Risks Not Assessed or Controls Not Implemented', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (262, 'AR_262', 1, 1, 15, 4, 'For AI systems using synthetic or LLM-generated data in model development or retraining, are generation methods formally documented, associated risks assessed, and quality validation controls implemented prior to use?', 'Yes – Generation Methods Documented, Risks Assessed & Quality Validation Controls Implemented | Partial – Documentation, Risk Assessment, or Quality Validation Incomplete or Inconsistently Applied | No – Not Documented, Assessed, or Controlled', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (263, 'AR_263', 1, 2, 7, 2, 'Is there a documented AI dataset retention and secure disposal policy ensuring that training, validation, testing, and operational datasets are retained only for defined purposes and securely archived or deleted when no longer required, in alignment with applicable legal and contractual requirements?', 'Yes – Policy Documented, Formally Approved & Consistently Applied | Partial – Policy Exists but Inconsistently Applied or Not Formally Approved | No – No Retention or Disposal Policy', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (264, 'AR_264', 1, 4, 13, 1, 'Are mechanisms in place to detect and govern shadow datasets — datasets used by AI teams outside formal registration, approval, or governance controls — including a defined process for retrospective registration, risk assessment, and remediation of any shadow datasets identified?', 'Yes – Detection Mechanisms in Place & Formal Governance Process for Shadow Dataset Remediation Defined | Partial – Detection Capability Exists but Governance or Remediation Process Informal or Incomplete | No – No Mechanism to Detect or Govern Shadow Datasets', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (265, 'AR_265', 1, 1, 17, 4, 'Does the organization monitor for data drift, distribution shift, or degradation in operational data used by deployed AI systems, and formally reassess data quality and representativeness at defined intervals or when drift signals are detected?', 'Yes – Continuous Monitoring in Place with Formal Reassessment at Defined Intervals or on Trigger | Partial – Periodic Reviews Only with No Continuous Monitoring or No Formal Reassessment Process | No – Not Monitored or Reassessed', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (266, 'AR_266', 1, 1, 15, 4, 'Has the organization defined a formal retraining governance checkpoint that mandates re-validation of data acquisition, quality, provenance, and preparation controls before a retrained or fine-tuned AI model is approved and redeployed?', 'Yes – Formal Checkpoint Defined & All Data Controls Re-Validated Before Redeployment | Partial – Checkpoint Exists but Not All Data Controls Are Re-Validated | No – No Retraining Governance Checkpoint Defined', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (267, 'AR_267', 1, 6, 14, 3, 'For cross-border or cross-jurisdictional data transfers used in AI systems, are the legal basis, applicable regulatory restrictions, and transfer safeguards formally documented and periodically reviewed to confirm ongoing compliance?', 'Yes – Legal Basis, Restrictions & Safeguards Fully Documented & Periodically Reviewed | Partial – Documented but Not Periodically Reviewed or Coverage Incomplete | No – Not Documented or Reviewed', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (268, 'AR_268', 1, 2, 10, 2, 'Does the organization apply data minimization principles to AI system design by formally restricting dataset size, feature inclusion, and attribute retention to what is demonstrably necessary for the defined AI purpose — and are these restrictions documented and subject to review when the AI purpose changes?', 'Yes – Data Minimization Formally Applied, Documented & Reviewed When Purpose Changes | Partial – Minimization Applied Inconsistently or Not Formally Documented | No – Data Minimization Principles Not Applied to AI System Design', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (269, 'AR_269', 1, 2, 7, 2, 'Where human labeling, annotation, or reinforcement learning from human feedback (RLHF) is used in AI development, has the organization defined quality standards, reviewer competence requirements, bias mitigation safeguards, and validation checks to ensure labeling integrity and consistency?', 'Yes – All Standards and Safeguards Formally Defined & Consistently Applied | Partial – Some Standards, Requirements, or Validation Checks Missing or Inconsistently Applied | No – No Quality Standards or Safeguards Defined for Human Labeling', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (270, 'AR_270', 1, 4, 4, 1, 'When integrating or fine-tuning third-party foundation or pretrained models, has the organization conducted a training data risk assessment covering dataset lineage, provenance gaps, demographic underrepresentation, labeling quality, contamination risks — including personally identifiable information and copyright exposure — and declared training data limitations?', 'Yes – Comprehensive Training Data Risk Assessment Conducted, Documented & Limitations Declared | Partial – Assessment Conducted but Some Risk Dimensions Not Evaluated or Limitations Not Declared | No – No Training Data Risk Assessment Conducted', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (271, 'AR_271', 1, 2, 10, 2, 'Has the organization assessed and documented how data subject rights — including access, correction, deletion, and objection — may impact AI training datasets, model retraining obligations, or the technical feasibility of removing individual data from trained model weights; and are findings reviewed and updated when relevant regulations or model architectures change?', 'Yes – Fully Assessed, Documented & Kept Current with Regulatory and Architectural Changes | Partial – Assessed but Not All Rights Addressed or Assessment Not Kept Current | No – Not Assessed', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (272, 'AR_272', 1, 2, 10, 2, 'Where data originally collected for non-AI purposes is used for AI training or evaluation, has the organization conducted a purpose compatibility assessment, legal basis validation, and data subject expectation analysis to confirm that secondary AI use complies with applicable legal, regulatory, and contractual obligations?', 'Yes – Full Three-Part Assessment Conducted, Documented & Secondary AI Use Confirmed Compliant | Partial – Assessment Conducted but Not All Three Elements Addressed or Not Documented | No – Not Assessed', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (273, 'AR_273', 1, 6, 18, 3, 'Are access events to AI training, validation, and testing datasets, feature stores, and model artifacts logged with sufficient detail, securely retained for a defined period, and periodically reviewed to detect unauthorized or policy-violating access?', 'Yes – Access Events Fully Logged with Sufficient Detail, Securely Retained & Periodically Reviewed | Partial – Logging Exists but Retention Period Undefined, Detail Insufficient, or No Periodic Review Conducted | No – Access Events Not Logged or Reviewed', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (274, 'AR_274', 1, 7, 16, 5, 'Has the organization defined governance criteria for selecting, validating, and bias-evaluating benchmark or evaluation datasets used to assess AI system performance, fairness, safety, or regulatory readiness — and are these criteria applied prior to deployment and at each material reassessment?', 'Yes – Governance Criteria Formally Defined & Consistently Applied at Deployment and Reassessment | Partial – Criteria Defined but Not Consistently Applied or Not Applied at Reassessment | No – No Governance Criteria Defined for Benchmark or Evaluation Datasets', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (275, 'AR_275', 1, 1, 21, 4, 'For AI systems using retrieval-augmented generation (RAG), dynamic retrieval, vector databases, or external document stores, are governance controls defined and implemented covering retrieval corpus curation, content provenance verification, update governance, bias validation, access controls, and output filtering to prevent injection of unauthorised or harmful content?', 'Yes – Comprehensive Governance Controls Defined, Implemented & Actively Maintained Across All Retrieval Components | Partial – Some Governance Controls Missing, Undefined, or Not Consistently Applied | No – Retrieval Layer Not Governed', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (276, 'AR_276', 1, 6, 34, 5, 'Has the organization implemented controls to ensure that users are informed when they are interacting with an AI system rather than a human, and that AI-generated content is labelled as such — including disclosure standards for text, image, audio, and video outputs?', 'Yes – AI Interaction Disclosure and Content-Labelling Controls Implemented Across All Output Types | Partial – Disclosure or Labelling Applied Inconsistently, or Coverage Limited to Certain Output Types | No – No Disclosure or Labelling Controls Implemented', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (277, 'AR_277', 1, 7, 36, 5, 'Where AI systems operate with significant autonomy or influence high-stakes decisions, has the organization defined and communicated the boundaries of AI decision-making authority — including the criteria under which human review is triggered and the mechanism by which affected parties may request escalation?', 'Yes – Decision-Making Boundaries Defined, Communicated & Human-Review Triggers and Escalation Mechanisms Formally Established | Partial – Boundaries Defined but Incompletely Communicated, or Escalation Mechanisms Not Formally Established | No – Decision-Making Boundaries Not Defined or Communicated', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (278, 'AR_278', 1, 6, 25, 3, 'Has the organization established and published an AI-specific acceptable-use policy that defines permitted and prohibited use cases, user obligations, consequences of misuse, and the process for reporting policy violations?', 'Yes – AI Acceptable-Use Policy Published, Covering Permitted | Prohibited Uses, User Obligations, Consequences & Reporting Process | Partial – Policy Exists but Is Incomplete, Unpublished, or Insufficiently Specific to AI Use Cases | No – No AI-Specific Acceptable-Use Policy Established', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (279, 'AR_279', 1, 4, 6, 3, 'Has the organization defined a policy for managing AI-related intellectual property — including ownership of AI-generated outputs, rights in training data, open-source licence compliance, and restrictions on use of third-party model weights?', 'Yes – AI IP Policy Formally Defined, Covering Ownership of Outputs, Training-Data Rights, Open-Source Compliance & Third-Party Model-Weight Restrictions | Partial – Policy Exists but Does Not Address All IP Risk Areas or Is Not Consistently Applied | No – No Formal AI Intellectual-Property Policy Defined', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (280, 'AR_280', 1, 6, 14, 3, 'Has the organization identified AI-related legal and regulatory obligations applicable across all jurisdictions in which it operates — and are processes in place to monitor regulatory developments, assess their impact on deployed AI systems, and update controls accordingly?', 'Yes – Jurisdiction-Specific AI Obligations Identified, Regulatory Monitoring Processes Established & Controls Updated Accordingly | Partial – Obligations Identified for Some Jurisdictions or Monitoring Processes Not Consistently Applied | No – AI-Related Legal and Regulatory Obligations Not Systematically Identified', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (281, 'AR_281', 1, 4, 4, 1, 'Where third-party or foundation models are deployed, has the organization determined which user disclosure obligations remain its responsibility, identified gaps in vendor-provided documentation, and incorporated AI transparency obligations into supplier contracts?', 'Yes – Responsibilities Determined, Documentation Gaps Addressed & Transparency Obligations Incorporated into Supplier Contracts | Partial – Responsibilities Partially Determined, Gaps Identified but Not Fully Addressed, or Contracts Not Yet Updated | No – Disclosure Responsibilities Not Assessed and Supplier Contracts Not Updated', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (282, 'AR_282', 1, 5, 8, 1, 'Has the organization established accessible mechanisms for users and affected parties to report adverse AI system impacts — and are processes in place for logging, investigating, and conducting trend analysis on reported incidents?', 'Yes – Accessible Reporting Mechanisms Established, and Logging, Investigation & Trend-Analysis Processes Fully Operational | Partial – Reporting Mechanisms Exist but Are Not Sufficiently Accessible, or Logging, Investigation, or Trend Analysis Is Incomplete | No – No Accessible Reporting Mechanisms or Incident-Processing Processes Established', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (283, 'AR_283', 1, 7, 36, 5, 'Where AI systems make or materially influence decisions affecting individual rights, access to services, or significant financial outcomes, has the organization established processes to provide meaningful, plain-language explanations of those decisions to affected individuals upon request?', 'Yes – Plain-Language Explanation Processes Established and Available to Affected Individuals Across All In-Scope Decision Types | Partial – Explanation Processes Exist for Some Decision Types or Are Not Consistently Accessible to Affected Individuals | No – No Explanation Processes Established for AI-Influenced Decisions', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (284, 'AR_284', 1, 5, 8, 1, 'Has the organization developed and maintained a formal AI incident communication plan — covering severity-tier classification, internal and external notification obligations, designated roles and responsibilities, regular testing, and a process for post-incident plan updates?', 'Yes – Formal AI Incident Communication Plan Established, Covering All Five Elements — Severity Tiers, Notification Obligations, Roles, Testing & Post-Incident Updates | Partial – Plan Exists but Does Not Address All Five Elements, or Testing and Updates Are Not Conducted Regularly | No – No Formal AI Incident Communication Plan Developed', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (285, 'AR_285', 1, 5, 8, 1, 'Has the organization defined AI-specific criteria for determining when an incident is reportable to external authorities — including harm-severity thresholds, scale-of-impact measures, applicable regulatory reporting obligations, notification timelines, responsible reporting parties, and evidence-preservation requirements?', 'Yes – AI-Specific External Reporting Criteria Formally Defined, Covering All Six Elements — Harm Thresholds, Scale Measures, Regulatory Obligations, Timelines, Responsible Parties & Evidence Preservation | Partial – Criteria Defined but Incomplete, or Not All Six Elements Are Addressed | No – No AI-Specific External Reporting Criteria Defined', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (286, 'AR_286', 1, 6, 34, 5, 'Has the organization established disclosure standards that communicate, in accessible language, the degree of system autonomy, the level of human oversight applied to AI-driven outputs, the party responsible for the system''s decisions, and the mechanism by which users may invoke or override human review?', 'Yes – Disclosure Standards Established, Covering System Autonomy, Oversight Level, Responsible Party & User Escalation Mechanism in Accessible Language | Partial – Disclosure Standards Exist but Do Not Address All Four Elements, or Are Not Consistently Applied Across In-Scope Systems | No – No Disclosure Standards for System Autonomy or Human Oversight Established', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (287, 'AR_287', 1, 6, 34, 5, 'Has the organization established standards for disclosing, where permissible and to the extent practicable, the general categories of training data used — including population characteristics, temporal coverage, and known representativeness limitations — to support user understanding of potential model biases?', 'Yes – Training-Data Disclosure Standards Established, Addressing Data Categories, Population Characteristics, Temporal Coverage & Representativeness Limitations Where Permissible | Partial – Disclosure Standards Exist but Do Not Address All Four Dimensions, or Are Applied Inconsistently | No – No Training-Data Disclosure Standards Established', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (288, 'AR_288', 1, 7, 37, 5, 'Has the organization identified user groups that may be disproportionately affected by AI system outputs — including those with accessibility needs, lower digital literacy, or other vulnerability characteristics — and implemented proportionate safeguards such as enhanced explanations, simplified output formats, and clearly signposted escalation paths?', 'Yes – Vulnerable and Disproportionately Affected User Groups Identified and Proportionate Safeguards — Enhanced Explanations, Simplified Formats & Escalation Paths — Implemented | Partial – User Groups Identified but Safeguards Incomplete, Inconsistently Applied, or Not Proportionate to Risk | No – Vulnerable or Disproportionately Affected User Groups Not Identified and No Safeguards Implemented', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (289, 'AR_289', 1, 6, 25, 3, 'Has the organization defined a governance process for the periodic review, update, and formal approval of AI-facing documentation — including version control, a defined review cadence triggered by material system changes, and a process for communicating material updates to affected users?', 'Yes – Governance Process for AI Documentation Review Formally Defined, Covering Periodic Review, Version Control, Material-Change Triggers, Approval Workflow & User Communication | Partial – Process Exists but Does Not Address All Five Elements, or Review and Communication Are Not Consistently Performed | No – No Formal Governance Process for AI Documentation Review Defined', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (290, 'AR_290', 1, 6, 34, 5, 'Has the organization established governance controls to ensure that disclaimers and limitation notices attached to AI outputs accurately communicate material constraints — including review by risk, legal, and governance functions — and that these statements are updated when underlying model capabilities or risk profiles change?', 'Yes – Governance Controls for Disclaimer Accuracy Established, with Documented Review by Risk, Legal & Governance Functions, and an Update Process Tied to Material Capability or Risk Changes | Partial – Disclaimer Controls Exist but Review Functions Are Not All Engaged, or Update Process Is Not Consistently Triggered by Material Changes | No – No Governance Controls for Disclaimer Accuracy or Review Established', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (291, 'AR_291', 1, 6, 18, 3, 'Does the organization conduct periodic trend analysis of adverse impact reports, categorised by incident type, severity, and AI system -- with findings reviewed by the governance function and integrated into risk reassessment and system improvement planning?', 'Yes -- Periodic Trend Analysis Conducted, Categorised by Incident Type, Severity & AI System, with Findings Reviewed by Governance and Integrated into Risk Reassessment and System Improvement Planning | Partial -- Trend Analysis Conducted Informally or Inconsistently, or Findings Not Reviewed by Governance or Not Integrated into Risk and Improvement Processes | No -- No Trend Analysis of Adverse Impact Reports Conducted', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (292, 'AR_292', 1, 5, 8, 1, 'Where an AI incident may have caused users to receive materially affected or harmful outputs, does the organization have a documented obligation and process for notifying affected users in a timely manner -- including defined notification timelines, prescribed content standards, and retention of all notification and incident records?', 'Yes -- User Notification Obligation Formally Documented, Timely Notification Process Established with Defined Timelines and Content Standards, and All Notification and Incident Records Retained | Partial -- Notification Obligation Documented but Process Is Informal, Timelines or Content Standards Not Defined, or Records Not Systematically Retained | No -- No Documented User Notification Obligation or Process Established', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (293, 'AR_293', 1, 6, 34, 5, 'Does the organization maintain a formally governed public AI transparency framework -- ensuring all externally facing AI communications are subject to pre-publication review by risk, legal, and compliance functions, prohibiting misleading capability claims, and verifying alignment with internal technical documentation?', 'Yes -- Formal Public Transparency Framework Established, with Pre-Publication Review by Risk, Legal & Compliance, Misleading Capability Claims Prohibited, and Internal Alignment Verified | Partial -- Framework Exists but Pre-Publication Reviews Are Conducted Inconsistently, Not All Functions Are Engaged, or Internal Alignment Is Not Systematically Verified | No -- No Public Transparency Governance Framework or Pre-Publication Review Process Established', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (294, 'AR_294', 1, 7, 16, 5, 'Where bias or fairness limitations have been identified through testing or operational monitoring, does the organization disclose those limitations to relevant users and interested parties in a manner proportionate to their materiality and risk classification -- and are disclosures updated when bias monitoring identifies changes?', 'Yes -- Bias and Fairness Limitations Disclosed Proportionately to Materiality and Risk Classification, and Disclosures Updated When Monitoring Identifies Changes | Partial -- Partial Disclosure Only -- Either Not Proportionate to Risk, Not Consistently Updated, or Not Communicated to All Relevant Parties | No -- Identified Bias and Fairness Limitations Not Disclosed', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (295, 'AR_295', 1, 6, 25, 3, 'Has the organization defined and implemented retention and archival requirements for all AI transparency artefacts -- including historical user documentation, model cards, regulatory submissions, and incident communications -- with integrity protection and version dating to demonstrate what was disclosed at any specific point in time?', 'Yes -- Retention and Archival Requirements Fully Defined and Implemented for All AI Transparency Artefact Types, with Integrity Protection and Version Dating Applied | Partial -- Requirements Defined but Not Fully Implemented, or Integrity Protection or Version Dating Absent for Some Artefact Types | No -- No Retention or Archival Requirements Defined for AI Transparency Artefacts', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (296, 'AR_296', 1, 6, 18, 3, 'Does the organization implement active controls to detect inconsistencies between AI system information disclosed across different channels -- including marketing, technical documentation, model cards, and regulatory submissions -- through periodic structured reconciliation reviews, with findings documented and remediation tracked?', 'Yes -- Active Cross-Channel Reconciliation Controls Implemented, Structured Reconciliation Reviews Conducted Periodically, and Findings Documented with Remediation Tracked | Partial -- Periodic Reviews Conducted but Reconciliation Process Is Informal, or Findings Are Not Systematically Documented or Remediation Tracked | No -- No Cross-Channel Consistency Controls or Reconciliation Reviews Implemented', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (297, 'AR_297', 1, 7, 38, 5, 'Has the organization formally defined and documented responsible AI use processes, integrated those processes into operational workflows and access controls -- rather than maintaining them as standalone policies -- and designated a process owner accountable for their currency and updating when systems change or incidents indicate inadequacy?', 'Yes -- Responsible AI Use Processes Formally Defined, Operationally Integrated into Workflows and Access Controls, and Actively Maintained by a Designated Process Owner | Partial -- Processes Defined but Not Operationally Integrated, Not Actively Maintained, or a Designated Process Owner Has Not Been Formally Appointed | No -- No Formal Responsible AI Use Processes Defined or Operationally Implemented', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (298, 'AR_298', 1, 8, 26, 6, 'Does the organization provide role-differentiated responsible AI use training for all individuals involved in operating, deploying, or using AI systems -- with training completion recorded, content refreshed upon material system or regulatory changes, and access to high-risk AI roles conditioned on verified training completion?', 'Yes -- Role-Differentiated Responsible AI Use Training Provided, Completion Recorded, Content Refreshed on Material Changes, and Access to High-Risk Roles Conditioned on Verified Completion | Partial -- Training Exists but Is Not Role-Differentiated, Completion Is Not Recorded or Enforced, or Access-Gating Is Not Applied to High-Risk Roles | No -- No Responsible AI Use Training Provided', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (299, 'AR_299', 1, 5, 8, 1, 'Has the organization documented a formal process for reporting, investigating, and escalating suspected misuse, out-of-scope use, or unexpected harmful AI system behaviour -- with defined reporting timelines, escalation criteria, designated accountability for remediation, and systematic retention of all process records?', 'Yes -- Formal Misuse Reporting, Investigation & Escalation Process Documented and Operational, Covering Defined Timelines, Escalation Criteria, Remediation Accountability & Records Retention | Partial -- Process Documented but Incomplete -- Timelines, Escalation Criteria, or Remediation Accountability Not Fully Defined, or Records Not Consistently Retained | No -- No Formal Misuse Reporting, Investigation, or Escalation Process Documented', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (300, 'AR_300', 1, 6, 29, 3, 'Has the organization defined actionable responsible AI use objectives with measurable indicators or behavioural criteria -- used to inform training content and operational monitoring -- and are those objectives reviewed and updated when the AI portfolio changes, regulatory requirements change, or monitoring data indicates that current objectives are not preventing harm?', 'Yes -- Actionable Responsible AI Use Objectives Defined with Measurable Indicators or Behavioural Criteria, Integrated into Training and Monitoring, and Reviewed and Updated When Portfolio, Regulatory, or Monitoring Triggers Arise | Partial -- Objectives Defined but Aspirational Rather Than Measurable, Rarely Updated, or Not Integrated into Training Content or Operational Monitoring | No -- No Responsible AI Use Objectives Defined', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (301, 'AR_301', 1, 7, 39, 3, 'Has the organization formally defined and documented the intended use of each AI system -- including tasks supported, user populations, deployment environments, and explicit out-of-scope and prohibited use boundaries -- with jurisdiction-specific compliance requirements assessed where systems are deployed across multiple jurisdictions?', 'Yes -- Intended Use, User Populations, Deployment Environments & Use Boundaries Formally Documented for Each AI System, and Jurisdiction-Specific Compliance Assessed Where Applicable | Partial -- Intended Use Defined but Use Boundaries or Jurisdiction-Specific Compliance Assessment Incomplete, or Documentation Not Maintained for All Systems | No -- Intended Use Not Formally Defined or Documented for AI Systems', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (302, 'AR_302', 1, 4, 13, 1, 'Does the organization implement operational controls to constrain or detect AI system use outside intended use documentation -- requiring governance approval for all proposed new use cases -- and is active monitoring in place to detect out-of-scope use, with detected violations triggering a defined response process?', 'Yes -- Operational Controls Implemented to Constrain or Detect Out-of-Scope Use, Governance Approval Required for New Use Cases, and Active Monitoring in Place with a Defined Violation Response Process | Partial -- Controls Exist but Active Monitoring Is Absent or Incomplete, Governance Approval Is Not Consistently Required, or a Violation Response Process Is Not Formally Defined | No -- No Operational Controls or Active Monitoring for Out-of-Scope AI System Use Implemented', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (303, 'AR_303', 1, 4, 4, 1, 'Where AI systems are deployed to or through third parties, does the organization impose binding contractual requirements for use in accordance with intended use documentation -- covering prohibition of out-of-boundary use, reporting obligations for detected misuse, and adherence to the organization''s responsible AI use policies?', 'Yes -- Binding Contractual Requirements Imposed on All Third Parties, Covering Intended-Use Compliance, Prohibition of Out-of-Boundary Use, Misuse Reporting Obligations & Responsible-Use Policy Adherence | Partial -- Contractual Requirements Exist but Are Incomplete, Do Not Cover All Four Elements, or Are Not Consistently Enforced Across All Third-Party Relationships | No -- No Binding Contractual Requirements Imposed on Third Parties for AI System Use', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (304, 'AR_304', 1, 6, 18, 3, 'Does the organization conduct periodic assessments to evaluate whether AI systems are being used in practice in accordance with their intended use documentation -- reviewing operational logs, incident reports, and monitoring outputs to identify gaps or out-of-boundary use, with findings documented and actioned?', 'Yes -- Periodic Assessments Conducted, Reviewing Operational Logs, Incident Reports & Monitoring Outputs to Identify Out-of-Boundary Use, with Findings Documented and Actioned | Partial -- Assessments Conducted Informally or Infrequently, Not All Three Evidence Sources Reviewed, or Findings Not Consistently Documented or Actioned | No -- No Periodic Assessments of AI System Use Against Intended Use Documentation Conducted', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (305, 'AR_305', 1, 7, 19, 5, 'Where AI systems support high-stakes decisions affecting individuals'' rights, safety, or material interests, has the organization defined and enforced minimum human oversight requirements -- specifying the nature, frequency, and individual accountability for human review prior to action being taken?', 'Yes -- Minimum Human Oversight Requirements Formally Defined and Enforced for All High-Stakes AI Decisions, Specifying Nature, Frequency & Individual Accountability for Human Review Prior to Action | Partial -- Requirements Defined but Not Consistently Enforced, or Nature, Frequency, or Individual Accountability Not Fully Specified | No -- No Minimum Human Oversight Requirements Defined for High-Stakes AI Decisions', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (306, 'AR_306', 1, 7, 37, 5, 'Has the organization assessed the risk of automation bias and implemented countermeasures proportionate to the system risk classification — including user guidance, interface design controls, mandatory review requirements, and periodic assessment of whether human oversight is exercised meaningfully rather than nominally?', 'Yes – Automation Bias Risk Formally Assessed and Countermeasures Proportionate to Risk Classification Implemented — Covering User Guidance, Interface Design Controls, Mandatory Review Requirements, and Periodic Meaningful-Oversight Assessment | Partial – Automation Bias Risk Assessed but Countermeasures Incomplete, Not Proportionate to Risk Classification, or Meaningful-Oversight Assessment Not Conducted Periodically | No – Automation Bias Risk Not Assessed and No Countermeasures Implemented', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (307, 'AR_307', 1, 4, 13, 1, 'Has the organization defined a policy governing the use of unsanctioned AI tools and services — specifying categories requiring prior assessment, prohibited tools, and controls preventing the submission of sensitive data to unapproved systems — with the policy technically enforced, monitored for violations, and subject to defined consequences for non-compliance?', 'Yes – Unsanctioned AI Use Policy Defined and Technically Enforced, with Prohibited Tools Specified, Sensitive-Data Controls Implemented, Monitoring in Place, and Defined Consequences for Violations | Partial – Policy Exists but Is Not Technically Enforced, Monitoring Is Absent or Informal, or Consequences for Violations Are Not Defined | No – No Policy Governing the Use of Unsanctioned AI Tools or Services Defined', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (308, 'AR_308', 1, 1, 1, 1, 'Where AI systems are used in combination — including pipelines, agentic architectures, and model chaining — has the organization assessed the combined use context as a distinct governance object with an aggregate risk assessment and formal governance approval, and is the combined system monitored for drift in constituent systems that would affect the overall risk profile?', 'Yes – Combined AI System Use Formally Assessed as a Distinct Governance Object, Aggregate Risk Assessed, Governance Approval Obtained, and Drift Monitoring Implemented Across Constituent Systems | Partial – Combined Use Assessed or Approved but Drift Monitoring Absent, or Governance Approval Informal or Incomplete | No – Combined AI System Use Not Governed as a Distinct Governance Object', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (309, 'AR_309', 1, 8, 26, 6, 'What proportion of individuals with operational AI system access have completed role-appropriate responsible use training in the current review period?', 'Yes – 90–100% of Individuals with Operational AI System Access Have Completed Role-Appropriate Responsible Use Training in the Current Review Period | Partial – 50–89% Completion Achieved — Training Coverage Incomplete for a Significant Minority (50–69%) or Near-Complete but Below Target (70–89%) | No – Fewer Than 50% of Individuals with Operational AI System Access Have Completed Required Responsible Use Training', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (310, 'AR_310', 1, 7, 39, 3, 'What proportion of AI systems currently in operational use have a formally documented and governance-approved intended use specification?', 'Yes – 90–100% of Operational AI Systems Have a Formally Documented and Governance-Approved Intended Use Specification | Partial – 50–89% of Operational AI Systems Have a Documented Intended Use Specification — Coverage Incomplete Across Most Systems (50–69%) or a Significant Minority (70–89%) | No – Fewer Than 50% of Operational AI Systems Have a Formally Documented and Governance-Approved Intended Use Specification', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (311, 'AR_311', 1, 5, 8, 1, 'How would the organization characterise the volume of misuse incidents, out-of-scope use events, or unsanctioned AI tool violations reported and investigated in the current review period?', 'Yes – Low Volume of Incidents Reported and Investigated, Consistent with Portfolio Size and Confirmed as Indicative of an Effective Reporting Culture Rather Than Under-Reporting | Partial – Moderate Volume with Emerging Patterns Under Active Review, or Zero Incidents Reported but Confidence in the Effectiveness of the Reporting Culture Has Not Been Formally Confirmed | No – High Volume Indicating Systemic Control Failures, or Zero Incidents Reported with No Evidence of an Effective Reporting Culture', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (312, 'AR_312', 1, 7, 19, 5, 'What proportion of high-stakes AI-informed decisions subject to mandatory human oversight requirements received documented human review prior to action being taken in the current review period?', 'Yes – 90–100% of High-Stakes AI-Informed Decisions Subject to Mandatory Human Oversight Requirements Received Documented Human Review Prior to Action in the Current Review Period | Partial – 50–89% Compliance Achieved — Documented Human Review Completed for Most Decisions (70–89%) or Only Some Decisions (50–69%) Subject to Mandatory Oversight Requirements | No – Fewer Than 50% of High-Stakes AI-Informed Decisions Received Documented Human Review — Material Non-Compliance with Human Oversight Requirements', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (313, 'AR_313', 1, 6, 29, 3, 'How would the organization assess progress against its documented responsible AI use objectives in the current review period?', 'Yes – All or Substantially All Documented Responsible AI Use Objectives Met in the Current Review Period, with Any Minor Gaps Formally Identified, Documented, and Remediated | Partial – Most Objectives Met with Minor Gaps and Active Remediation Plans in Place, or Some Objectives Met with Material Gaps Formally Identified | No – Most or All Documented Responsible AI Use Objectives Not Met in the Current Review Period', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (314, 'AR_314', 1, 6, 22, 5, 'Does the organization define and enforce a documented consequence framework for violations of responsible AI use requirements — with graduated consequences formally integrated into HR disciplinary procedures and contractor agreements?', 'Yes – Formal Consequence Framework Defined and Enforced, with Graduated Consequences Integrated into HR Disciplinary Procedures and Contractor Agreements | Partial – Consequence Framework Exists but Is Not Consistently Enforced, Not Integrated into HR or Contractor Agreements, or Consequences Are Not Graduated | No – No Consequence Framework for Responsible AI Use Violations Defined', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (315, 'AR_315', 1, 2, 2, 2, 'Does the organization implement documented mechanisms for restricting or revoking AI system access for individuals found to be in violation of responsible use requirements — with defined eligibility criteria, designated revocation authority, a formal reinstatement process, and audit records of all revocation and reinstatement actions?', 'Yes – Formal Access Restriction and Revocation Mechanisms Documented and Operational, Covering Defined Criteria, Designated Authority, Reinstatement Process, and Audit Records | Partial – Mechanisms Exist but Are Not Formally Documented, Criteria or Authority Are Not Clearly Defined, or Audit Records Are Not Consistently Maintained | No – No Documented Access Restriction or Revocation Mechanisms Implemented', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (316, 'AR_316', 1, 1, 5, 1, 'Has the organization defined criteria for suspending AI system operation — covering drift beyond defined thresholds, safety incidents, regulatory inquiry, and monitoring failures — with a designated authority empowered to invoke suspension immediately, a communication process for affected users and stakeholders, and formally defined reinstatement criteria?', 'Yes – AI System Suspension Criteria Formally Defined Across All Four Trigger Types, Designated Suspension Authority Established, User and Stakeholder Communication Process in Place, and Reinstatement Criteria Formally Defined | Partial – Suspension Criteria Defined but Not Covering All Four Trigger Types, or Designated Authority, Communication Process, or Reinstatement Criteria Not Fully Established | No – No AI System Suspension Criteria or Designated Authority Defined', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (317, 'AR_317', 1, 9, 32, 7, 'Does the organization measure and report the energy and water usage associated with major AI training or fine-tuning runs, and consider ESG targets when approving large-scale training jobs or provider choices?', 'Yes – Energy & Water Usage Measured, Reported & ESG Targets Integrated into Approvals | Partial – Usage Measured but Not Reported or Not Linked to ESG Targets | No – Not Measured or Reported', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (318, 'AR_318', 1, 1, 15, 4, 'Before training or retraining AI models, does the organization verify that training data (a) covers current regulations or business rules and (b) reflects realistic class balances, rather than over-representing rare events compared to production reality?', 'Yes – Both Checks Consistently Applied Before Training | Partial – Checks Applied Inconsistently or for Some Criteria Only | No – Not Checked', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (319, 'AR_319', 1, 1, 17, 4, 'Does the organization regularly review whether key business definitions (e.g., churn, risk grades, product hierarchies) and underlying training data remain current, and update or retire models when those definitions or behaviours change materially?', 'Yes – Regular Reviews Conducted & Models Updated or Retired When Required | Partial – Reviews Conducted Irregularly or Response Actions Inconsistent | No – Not Reviewed', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (320, 'AR_320', 1, 1, 15, 4, 'Before training or retraining AI models, does the organization validate that target labels are not leaking into features and that synthetic or AI-generated data is used in a controlled way (e.g., capped proportions, quality checks) so that models continue to reflect real-world behaviour?', 'Yes – Label Leakage and Synthetic Data Controls Both Validated | Partial – One or Both Controls Applied Inconsistently | No – Neither Validated', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (321, 'AR_321', 1, 3, 3, 1, 'For AI-assisted development, does the organization enforce secure coding standards that prevent hardcoded secrets and detect auto-generated code that is difficult to maintain or review?', 'Yes – Secure Coding Standards Enforced with Automated Checks | Partial – Standards Defined but Not Consistently Enforced or Automated | No – No Secure Coding Standards', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (322, 'AR_322', 1, 1, 12, 4, 'For AI-related code and controls, does the organization review AI-generated tests for substantive coverage (not trivial assertions) and periodically test key AI controls — including monitoring, access, and fairness checks — for ongoing effectiveness?', 'Yes – Tests Reviewed for Substance & Key Controls Periodically Tested for Effectiveness | Partial – Reviews or Periodic Tests Conducted Inconsistently | No – Neither Conducted', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (323, 'AR_323', 1, 5, 23, 4, 'Does the organization operate a controlled model release process that tracks versions from testing to production and validates that disaster-recovery or backup models match approved production versions before failover?', 'Yes – Controlled Release Process with Version Tracking & DR Validation | Partial – Process Exists but DR Validation or Version Tracking Incomplete | No – No Controlled Model Release Process', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (324, 'AR_324', 1, 3, 3, 1, 'Are AI APIs and orchestration platforms managed with robust secret management — including short-lived tokens, vaults, and key rotation — and hardened container and orchestrator configurations to limit the blast radius of a compromised AI container or credential?', 'Yes – Robust Secret Management & Hardened Configurations Fully in Place | Partial – Some Controls Present but Not Comprehensive | No – No Formal Secret Management or Hardening', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (325, 'AR_325', 1, 6, 14, 3, 'For AI systems involved in pricing or market recommendations, does the organization monitor for patterns that may indicate algorithmic collusion or unlawful price discrimination across customer segments or devices?', 'Yes – Monitoring in Place for Both Collusion and Discrimination Patterns | Partial – Monitoring for One Pattern Only or Applied Inconsistently | No – Not Monitored', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (326, 'AR_326', 1, 4, 4, 1, 'Do the organization''s contracts and vendor due diligence for AI development explicitly address downstream labour practices — such as data labeling and content moderation — to prevent unethical or undisclosed sub-contracting?', 'Yes – Contracts and Due Diligence Both Explicitly Address Labour Practices | Partial – Addressed in Contracts but Not Systematically in Due Diligence | No – Not Addressed', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (327, 'AR_327', 1, 4, 40, 1, 'Do the organization''s onboarding and credit processes include controls specifically designed to detect synthetic or AI-generated identities — such as deepfake checks, cross-channel verification, and device fingerprinting?', 'Yes – Specific Controls Implemented for AI-Generated Identity Detection | Partial – Some Controls Present but Not Comprehensive | No – No Specific Controls', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (328, 'AR_328', 1, 2, 2, 2, 'For AI meeting assistants and knowledge-search tools, does the organization (a) obtain and record consent where required, and (b) enforce access controls to prevent restricted or conflict-of-interest matters from being surfaced to unauthorized staff?', 'Yes – Consent Obtained and Access Controls Enforced | Partial – One Requirement Met but Not Both | No – Neither Implemented', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (329, 'AR_329', 1, 6, 18, 3, 'Is there a persistent, tamper-evident log of all material AI-assisted decisions and actions, including timestamp, model version, input summary, and — where applicable — the identity of the human approver?', 'Yes – Persistent, Tamper-Evident Logging Fully Implemented | Partial – Logging Exists but Not Tamper-Evident or Missing Required Fields | No – No Formal Decision Logging', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (330, 'AR_330', 1, 7, 36, 5, 'Can the organization identify the specific knowledge base version or RAG source document referenced in generating a given AI output — and if a decision is challenged, trace that output back to the specific datasets or sources used?', 'Yes – Full Source Traceability Implemented for All AI Outputs | Partial – Traceability Available for Some Systems or Output Types Only | No – Not Traceable', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (331, 'AR_331', 1, 6, 30, 3, 'For high-risk AI systems, is there a named owner and a regulatory-ready documentation pack — covering system design, training data sources, testing results, monitoring arrangements, change history, and key decisions — that is kept current?', 'Yes – Named Owner and Current Regulatory-Ready Documentation Pack in Place | Partial – Owner Assigned but Documentation Incomplete or Not Current | No – Neither in Place', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (332, 'AR_332', 1, 7, 16, 5, 'For AI systems that target offers, discounts, or pricing, does the organization review outcomes for geographic or demographic bias to ensure they do not systematically disadvantage protected groups or breach fair-trading or anti-discrimination laws?', 'Yes – Outcomes Reviewed for Bias and Legal Compliance Confirmed | Partial – Reviews Conducted Inconsistently or Covering Some Dimensions Only | No – Not Reviewed', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (333, 'AR_333', 1, 6, 24, 3, 'Is there a formally documented AI governance structure — such as a Board committee or equivalent — with a clear mandate requiring major AI initiatives to pass through ethics and oversight review, and that assigns unambiguous accountability for AI risk decisions?', 'Yes – Documented Governance Structure with Clear Mandate & Accountability in Place | Partial – Structure Exists but Mandate or Accountability Unclear | No – No Formal AI Governance Structure', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (334, 'AR_334', 1, 3, 3, 1, 'Has the organization assessed and tested its AI models and RAG pipelines against adversarial threats — such as crafted inputs, malicious context documents, or poisoned training data — designed to manipulate model behaviour?', 'Yes – Adversarial Assessment and Testing Formally Conducted | Partial – Assessed or Tested for Some Threat Types Only | No – Not Assessed or Tested', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (335, 'AR_335', 1, 1, 12, 4, 'When training and validating AI models, does the organization enforce clean separation between training and test sets — including guarding against leakage from logs or replayed traffic — and periodically re-verify that no training data has contaminated evaluation datasets?', 'Yes – Clean Separation Enforced and Periodically Re-Verified | Partial – Separation Enforced Initially but Not Periodically Re-Checked | No – Not Enforced', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (336, 'AR_336', 1, 4, 4, 1, 'Does the organization manage risks from third-party or embedded AI components — such as SaaS plugins — and enforce policies for AI-generated content labelling and watermarking, including detecting and responding when users attempt to remove watermarks?', 'Yes – Third-Party Risks Managed and Content Labelling & Watermarking Enforced | Partial – One Area Addressed but Not Both | No – Neither Addressed', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (337, 'AR_337', 1, 5, 8, 1, 'Does the organization conduct structured AI failure scenario analysis or stress testing — such as tabletop exercises or red-teaming — to ensure it is prepared for AI outages, misbehaviour, or attacks, rather than responding ad hoc when issues arise?', 'Yes – Structured Exercises Conducted at Defined Intervals | Partial – Exercises Conducted Informally or Infrequently | No – Not Conducted', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (338, 'AR_338', 1, 6, 33, 5, 'For AI-enabled interfaces — including web, mobile, kiosks, and chat — does the organization assess and remediate accessibility against recognized standards such as WCAG, including support for assistive technologies and alternative interaction modes?', 'Yes – Accessibility Assessed Against WCAG and Remediated | Partial – Assessed but Not Fully Remediated | No – Not Assessed', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (339, 'AR_339', 1, 8, 41, 6, 'Does the organization review and adjust AI-driven performance or productivity metrics to ensure they do not unfairly penalize certain roles or employees, and are staff able to formally challenge AI-generated evaluations?', 'Yes – Metrics Reviewed for Fairness and Formal Challenge Mechanism in Place | Partial – One Element in Place but Not Both | No – Neither in Place', NULL, FALSE);
