INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (344, 'AR_344', 1, 4, 40, 1, 'Does the organization use controls — such as CAPTCHAs, device fingerprinting, velocity checks, and identity verification — to detect and block automated creation of fake accounts or abuse of loyalty and sign-up incentives?', 'Yes – Controls in Place Across All Primary Attack Vectors | Partial – Some Controls Present but Not Comprehensive | No – No Controls in Place', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (345, 'AR_345', 1, 4, 40, 1, 'For voice-based or call-centre authentication, does the organization use strong anti-spoofing and step-up verification — such as knowledge factors, device checks, and callbacks — to protect against cloned or deepfaked voices?', 'Yes – Strong Anti-Spoofing and Step-Up Verification in Place | Partial – Basic Controls Only, Comprehensive Verification Absent | No – Not in Place', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (346, 'AR_346', 1, 8, 28, 6, 'Maintain formal, up-to-date RACI documentation for all AI systems covering accountable executive, responsible owner, consulted risk/legal/technical functions, and informed stakeholders — reviewed at least annually or upon material change.', 'Yes | Partial | No', NULL, FALSE);
