INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (397, 'AR_397', 1, 3, 3, 1, 'For AI APIs and endpoints, have you assessed threats such as man-in-the-middle interception and model extraction, and implemented protections like strong encryption, authentication, rate limiting, and anomaly detection on query patterns?', 'Yes | Partial | No | Not Applicable', NULL, FALSE);
