INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (399, 'AR_399', 1, 3, 3, 1, 'Do you test models and data pipelines for adversarial techniques such as poisoned training samples, multimodal payloads (e.g., steganographic images or audio), or AI-generated polymorphic malware that could act as hidden triggers or bypass traditional detection?', 'Yes | Partial | No | Not Applicable', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (400, 'AR_400', 1, 4, 40, 1, 'Have you implemented controls to prevent abuse of AI channels for replay-style attacks (e.g., resubmitting signed requests) and for highly personalised phishing campaigns that use AI to generate convincing messages at scale?', 'Yes | Partial | No | Not Applicable', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (401, 'AR_401', 1, 4, 13, 1, 'Do you enforce policies and technical controls that restrict staff from (a) using AI to hide or generate malicious code, (b) installing unvetted plugins or extensions, and (c) pasting sensitive or regulated data into unsanctioned consumer AI tools?', 'Yes | Partial | No', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (402, 'AR_402', 1, 4, 13, 1, 'Beyond the official AI register, do you actively search for and bring into governance any shadow AI tools, workflows, or automations (e.g., unsanctioned bots, spreadsheets with embedded LLM calls) that could impact customers or regulated processes?', 'Yes | Partial | No', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (403, 'AR_403', 1, 8, 26, 6, 'Do frontline users receive training that (a) explains the cultural and contextual limits of AI outputs and (b) explicitly encourages them to challenge or override AI suggestions when they appear inappropriate or wrong?', 'Yes | Partial | No | Not Applicable', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (404, 'AR_404', 1, 8, 41, 6, 'Have you formally assessed and addressed the workforce impacts of AI (e.g., communication, retraining, and redeployment plans) and do you periodically measure morale or productivity impacts related to fear of AI replacement?', 'Yes | Partial | No', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (405, 'AR_405', 1, 7, 19, 5, 'For AI systems that can generate or route public-facing content, do you (a) define high-risk topics, (b) apply additional human review or fact-checking, and (c) monitor for amplification of false or harmful narratives across channels?', 'Yes | Partial | No | Not Applicable', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (406, 'AR_406', 1, 8, 41, 6, 'Do you have a documented approach to AI-assisted work that includes guardrails to preserve core skills (e.g., training, rotation, limits on AI use for juniors) and periodic checks that staff can still perform key tasks without AI support?', 'Yes | Partial | No | Not Applicable', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (407, 'AR_407', 1, 4, 4, 1, 'Before adopting or renewing critical AI services, do you assess vendor financial stability and maintain a contingency plan (e.g., alternative provider, internal fallback) if that vendor fails or exits the market?', 'Yes | Partial | No | Not Applicable', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (408, 'AR_408', 1, 4, 4, 1, 'For your AI vendors, do you map the chain of custody for data passed to AI sub-processors, ensuring no data helps train third-party foundation models without consent?', 'Yes | Partial | No | Not Applicable', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (409, 'AR_409', 1, 6, 22, 5, 'When AI influences important decisions, do your policies and disclosures clearly assign human accountability rather than suggesting that responsibility lies with the tool or vendor, and are escalation paths defined when outcomes are disputed?', 'Yes | Partial | No', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (410, 'AR_410', 1, 4, 13, 1, 'Do you have controls to prevent staff from pasting client-identifying or confidential data into public or consumer AI tools, and to manage conflicts of interest when AI is used across multiple clients or matters?', 'Yes | Partial | No | Not Applicable', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (411, 'AR_411', 1, 2, 10, 2, 'Before using internal HR or sensitive datasets to train or fine-tune AI models, do you (a) obtain appropriate governance approvals, (b) complete any required DPIA or AI impact assessment, and (c) confirm lawful bases and cross-border transfer compliance for that data?', 'Yes | Partial | No | Not Applicable', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (412, 'AR_412', 1, 7, 16, 5, 'Where AI supports or automates insurance or benefit claims decisions, have you validated that rules do not systematically deny valid claims, and do you provide clear escalation and human appeal mechanisms?', 'Yes | Partial | No | Not Applicable', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (413, 'AR_413', 1, 7, 36, 5, 'When AI influences important decisions, can you provide a meaningful explanation of the main factors, and are responsibilities defined so that staff are not held personally liable for errors they cannot see or technically prevent?', 'Yes | Partial | No', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (414, 'AR_414', 1, 7, 16, 5, 'For high-impact AI models (e.g., credit, hiring, customer treatment), do you test performance and error rates across key demographic groups and remediate when one group is consistently disadvantaged?', 'Yes | Partial | No | Not Applicable', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (415, 'AR_415', 1, 4, 40, 1, 'Are employees explicitly restricted and monitored from using AI tools (internal or external) with material non-public information (MNPI) or trade secrets, with training and surveillance designed to detect and respond to misuse?', 'Yes | Partial | No | Not Applicable', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (416, 'AR_416', 1, 7, 16, 5, 'For AI used in recruiting or triage (e.g., CV screening, case prioritisation), do you test for disparate impact across protected groups and adjust models or decision rules when bias is detected?', 'Yes | Partial | No | Not Applicable', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (417, 'AR_417', 1, 6, 27, 3, 'Do AI oversight bodies (e.g., AI committee, ethics lead, model risk lead) have (a) clearly defined authority to pause or stop deployments, (b) sufficient resourcing to review high-risk systems, and (c) regular reporting into the Board or equivalent?', 'Yes | Partial | No', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (418, 'AR_418', 1, 6, 24, 3, 'Has the Board formally approved an AI strategy and risk appetite, and does it receive regular, candid reporting on AI risk exposure, incidents, and remediation progress?', 'Yes | Partial | No', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (419, 'AR_419', 1, 6, 27, 3, 'Are AI oversight roles and committees independent from product and growth incentives (e.g., separate reporting lines, conflict-of-interest rules), and are executive KPIs balanced between AI growth and safe, compliant deployment?', 'Yes | Partial | No', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (420, 'AR_420', 1, 4, 4, 1, 'Before training or fine-tuning models on internal or customer data, do you require governance approval and confirm that third-party providers (e.g., API vendors) are contractually barred from using your inputs to train their public base models?', 'Yes | Partial | No | Not Applicable', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (421, 'AR_421', 1, 5, 8, 1, 'Do you have a defined process to identify AI-related incidents (e.g., safety, discrimination, privacy), assess reportability, and notify regulators or clients within required timelines, with links to DPIA or AI impact assessments where applicable?', 'Yes | Partial | No | Not Applicable', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (422, 'AR_422', 1, 5, 8, 1, 'Are robotics incidents independently investigated from safety, legal, technological, union, and community perspectives, and are results transparently communicated to stakeholders and regulators as required?', 'Yes | Partial | No | Not Applicable', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (423, 'AR_423', 1, 6, 22, 5, 'Has the organisation defined a responsibility allocation framework specifying how AI lifecycle responsibilities are distributed across the organisation, partners, suppliers, and customers — documented at the level of individual AI systems with named accountable parties per responsibility type — and actively maintained by a designated owner with updates when relationships, new AI deployments, or regulatory obligations change?', 'Yes – Framework Defined, System-Level Granularity & Actively Maintained | Partial – Framework Exists but Lacks Granularity or Is Poorly Maintained | No – No Responsibility Allocation Framework', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (424, 'AR_424', 1, 4, 4, 1, 'Are AI lifecycle responsibility allocations reflected in legally binding instruments (contracts, SAs, DPAs, customer terms) specifying each party''s accountability for AI outcomes, incident notifications, audit rights, and remediation — with shared accountability boundaries explicitly defined and agreed, including incident attribution processes and escalation for disputed cases?', 'Yes – Contractually Enforced & Shared Boundaries Defined | Partial – Contractual Coverage Exists but Shared Boundaries or Key Terms Missing | No – Responsibility Allocations Not Contractually Enforced', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (425, 'AR_425', 1, 4, 4, 1, 'Has the organisation established a documented process for assessing AI-relevant suppliers prior to onboarding and at defined intervals — evaluating AI-specific governance dimensions (data quality, model transparency, bias controls, safety testing, incident response, regulatory compliance) and jurisdictional risks — with assessment currency tracked per supplier and stale assessments triggering a defined escalation process?', 'Yes – Process Established, AI Dimensions Covered, Jurisdictions Assessed & Currency Tracked | Partial – Process Exists but AI Dimensions, Jurisdictions, or Currency Tracking Incomplete | No – No Supplier Responsible AI Assessment Process', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (426, 'AR_426', 1, 4, 4, 1, 'Does the organisation maintain a current governed inventory of all AI-relevant suppliers — with each supplier''s contribution type, criticality tier, assessment status, and contract review date recorded — and do supplier contracts include binding AI-specific obligations covering data governance, model documentation, incident notification timelines, audit rights, and consequences for non-compliance?', 'Yes – Inventory Maintained & Contracts Include AI-Specific Obligations | Partial – Inventory Exists or Contracts Partially Compliant but Both Not Fully in Place | No – No Supplier Inventory or AI-Specific Contract Obligations', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (427, 'AR_427', 1, 4, 4, 1, 'Does the organisation monitor ongoing supplier performance against responsible AI requirements — tracking changes to AI governance practices, regulatory compliance status, incident history, and material component changes — with findings used to trigger reassessment, contract review, or remediation where non-conformance or deterioration is identified?', 'Yes – Ongoing Monitoring in Place & Findings Drive Action | Partial – Monitoring Exists but Findings Not Systematically Actioned | No – No Ongoing Supplier Performance Monitoring', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (428, 'AR_428', 1, 4, 4, 1, 'Where AI systems incorporate externally developed models, datasets, or AI components, has the organisation assessed and documented known limitations, biases, data provenance, licensing constraints, and downstream deployment restrictions — with these communicated to all individuals operating the systems, operationally enforced through intended use documentation and deployment controls, and reviewed when components are materially updated?', 'Yes – Risks Documented & Operationally Enforced | Partial – Documented but Not Communicated or Enforced Operationally | No – Not Assessed or Documented | Not Applicable', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (429, 'AR_429', 1, 4, 4, 1, 'Does the organisation require AI-relevant suppliers to disclose all AI-relevant subcontractors or subprocessors — maintaining a current subprocessor register, providing advance notification before engaging new subprocessors, flowing down responsible AI obligations, and granting the organisation the right to object to or review material subcontracting arrangements affecting AI system risk?', 'Yes – Subprocessor Transparency & Flow-Down Requirements Fully in Place | Partial – Some Requirements in Place but Incomplete | No – No Subprocessor Disclosure Requirements', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (430, 'AR_430', 1, 4, 4, 1, 'Do contracts with AI-relevant suppliers require advance notification of material changes to AI models, datasets, training methods, deployment architecture, or safety controls — with defined notification timelines proportionate to change materiality, a review window before continued reliance, and a documented process for assessing whether the change affects risk classification or intended use specifications?', 'Yes – Notification Requirements, Review Window & Impact Assessment Process All Defined | Partial – Some Requirements Defined but Others Missing | No – No Supplier Change Notification Requirements', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (431, 'AR_431', 1, 4, 4, 1, 'Has the organisation assessed and documented exit and transition risks for critical AI-relevant supplier relationships — covering technical dependencies, data portability rights, model replacement feasibility, business continuity during transition, and contractual provisions for responsible disengagement — assessed prior to onboarding and reviewed when dependency criticality changes materially?', 'Yes – Exit Risks Assessed & Contractual Provisions in Place | Partial – Partially Assessed or Contractual Provisions Incomplete | No – Exit Risks Not Assessed', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (432, 'AR_432', 1, 6, 11, 3, 'Has the organisation assessed concentration risk across AI-relevant supplier relationships — identifying where dependency on a single supplier, platform, or foundation model creates aggregate risk to multiple AI systems simultaneously — with concentration thresholds defined, threshold breaches triggering risk treatment, and diversification or contingency options evaluated?', 'Yes – Concentration Risk Assessed, Thresholds Defined & Contingency Options Evaluated | Partial – Concentration Risk Identified but Thresholds or Contingency Incomplete | No – Concentration Risk Not Assessed', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (433, 'AR_433', 1, 6, 34, 5, 'Has the organisation established a documented process for identifying and incorporating customer expectations relevant to responsible AI use (transparency, explainability, fairness, oversight, recourse) — with findings formally documented, used to inform AI system design and governance — and reviewed at defined intervals or when feedback, system changes, or regulatory requirements indicate a need to update?', 'Yes – Customer Expectations Formally Captured, Used to Inform Governance & Actively Maintained | Partial – Captured but Rarely Reviewed or Not Used to Inform Governance | No – No Formal Process to Capture Customer Expectations', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (434, 'AR_434', 1, 6, 34, 5, 'Does the organisation define and implement customer-facing AI disclosures — specifying AI involvement, limitations, conditions under which reliance is inappropriate, and recourse mechanisms — expressed in plain language appropriate to the customer population, provided proactively at or before the point of interaction, and reviewed and updated when AI system capabilities or limitations change materially?', 'Yes – Disclosures Defined, Plain Language, Proactive & Maintained | Partial – Disclosures Exist but Not Plain Language, Reactive, or Rarely Updated | No – No Customer-Facing AI Disclosures', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (435, 'AR_435', 1, 7, 19, 5, 'Does the organisation implement a documented mechanism enabling customers to raise concerns or query AI system outputs — with defined response timelines, designated accountability, and records retained — and where AI systems inform high-stakes individual decisions (credit, insurance, employment, healthcare, service eligibility), is a right-to-human-review mechanism in place with defined timelines and records?', 'Yes – Complaint Mechanism & Human Review Right Both Implemented | Partial – Complaint Mechanism Exists but Human Review Right Absent or Incomplete | No – No Customer Query or Complaint Mechanism | Not Applicable', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (436, 'AR_436', 1, 6, 29, 3, 'Does the organisation systematically capture, investigate, and analyse customer feedback and complaints related to AI system outputs — with findings used to identify governance gaps, inform system improvements, trigger risk reassessment where harm or fairness concerns are indicated, and reported to management review as a standing agenda item?', 'Yes – Systematic Analysis & Findings Formally Integrated into Governance | Partial – Captured but Analysis Informal or Not Formally Integrated | No – Not Systematically Captured or Analysed', NULL, FALSE);
