INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (438, 'AR_438', 1, 6, 34, 5, 'What proportion of customer-facing AI systems have disclosure materials that have been reviewed and confirmed current within the organisation''s defined review cadence?', '90–100% – Near Full Coverage | 70–89% – Majority Reviewed | 50–69% – Partial Coverage | Below 50% – Insufficient Coverage', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (439, 'AR_439', 1, 6, 29, 3, 'How would you characterise the volume and governance status of customer complaints, queries, or escalations related to AI system outputs or decisions received in the current review period?', 'All Complaints Received, Investigated & Resolved – Patterns Formally Reviewed | Complaints Received & Investigated but No Formal Pattern Analysis | Complaints Received but Investigation Incomplete | No Complaints Received and No Confidence in Reporting Culture', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (440, 'AR_440', 1, 6, 22, 5, 'What proportion of third-party AI relationships — including supplier, partner, and customer-operator relationships — have responsibility allocations reflected in binding contractual instruments reviewed within the organisation''s defined contract review cadence?', '90–100% – Near Full Contractual Coverage | 70–89% – Majority Covered | 50–69% – Partial Coverage | Below 50% – Material Accountability Gaps', NULL, FALSE);
INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (441, 'AR_441', 1, 6, 29, 3, 'How would you assess the overall state of third-party and customer relationship governance in the current review period — including supplier non-conformances, assessment findings, customer complaint trends, disputed responsibility attributions, and outstanding contractual remediation actions?', 'Well Governed – No Material Issues or All Issues Tracked with Remediation Plans | Minor Issues Identified & Being Managed | Moderate Issues with Some Unresolved Items | Significant Governance Gaps or Unresolved Material Issues', NULL, FALSE);
