INSERT INTO questions (question_id, qid_code, domain_id, dept_id, category_id, cluster_id, question_text, response_type, trigger_points, is_universal) VALUES (453, 'AR_B_12', 2, 6, 18, 3, 'Does the AI-powered transaction monitoring system produce audit-ready Suspicious Activity Reports (SARs) with explainable risk scores?', 'Yes | No | Partial | Not Applicable', 'Partial | No', FALSE);
